"""
xarm_action_manager - Action管理节点

功能说明:
1. 对外提供action服务器接收客户端请求
2. 将action转发到对应controller的action server
3. 通过controller_state_tracker协调xarm_manager进行控制器切换
"""

import rclpy
from rclpy.node import Node
from rclpy.action import ActionClient

from xarm_manager.tools import controller_state_tracker
from xarm_manager.action_config import get_all_action_configs


class XArmActionManagerNode(Node):
    """xarm_action_manager主节点"""

    def __init__(self):
        super().__init__('xarm_action_manager')
        self._init_action_servers()

    def _init_action_servers(self):
        """初始化action服务器"""
        self._action_servers = {}
        self._action_clients = {}
        self._action_configs = get_all_action_configs()

        for action_name, config in self._action_configs.items():
            self.get_logger().info(f"Creating action server: {action_name} -> {config.controller_action_name}")
            self._action_servers[action_name] = rclpy.action.ActionServer(
                self, config.action_type, action_name,
                goal_callback=lambda gh, an=action_name: self._action_goal_callback(gh, an),
                cancel_callback=lambda gh, an=action_name: self._action_cancel_callback(gh, an),
                execute_callback=lambda gh, an=action_name: self._action_execute_callback(gh, an)
            )
            self.get_logger().info(f"Creating action client: {config.controller_action_name}")
            self._action_clients[action_name] = ActionClient(self, config.action_type, config.controller_action_name)

    def _action_goal_callback(self, goal_handle, action_name):
        """处理收到的action goal"""
        self.get_logger().info(f"Received action goal for {action_name}")
        config = self._action_configs[action_name]
        controller_state_tracker.set_controller_required(config.controller_name, source='action')
        return rclpy.action.GoalResponse.ACCEPT

    def _action_cancel_callback(self, goal_handle, action_name):
        """处理action取消请求"""
        self.get_logger().info(f"Cancel request received for {action_name}")
        return rclpy.action.CancelResponse.ACCEPT

    def _action_execute_callback(self, goal_handle, action_name):
        """
        执行action goal

        注意: 这是同步执行的,不能使用spin,需要轮询等待future完成
        """
        config = self._action_configs[action_name]
        action_client = self._action_clients[action_name]
        incoming_goal = goal_handle.request

        self.get_logger().info(f"Executing action goal for {action_name}")

        # 等待controller action server就绪
        if not action_client.wait_for_server(timeout_sec=5.0):
            self.get_logger().error(f"Controller action server not available: {config.controller_action_name}")
            result_msg = config.create_result_msg(None)
            result_msg.success = False
            result_msg.result_msg = "Controller action server not available"
            controller_state_tracker.set_controller_unrequired(config.controller_name)
            return result_msg

        # 发送goal
        goal_msg = config.create_goal_msg(incoming_goal)
        future = action_client.send_goal_async(goal_msg)

        # 轮询等待future完成
        import time
        start_time = time.time()
        while not future.done() and (time.time() - start_time) < 5.0:
            pass

        if not future.done():
            self.get_logger().error(f"Timeout waiting for goal send: {action_name}")
            result_msg = config.create_result_msg(None)
            result_msg.success = False
            result_msg.result_msg = "Timeout waiting for goal send"
            controller_state_tracker.set_controller_unrequired(config.controller_name)
            return result_msg

        controller_goal_handle = future.result()
        if not controller_goal_handle or not controller_goal_handle.accepted:
            self.get_logger().error(f"Controller rejected the goal: {action_name}")
            result_msg = config.create_result_msg(None)
            result_msg.success = False
            result_msg.result_msg = "Controller rejected the goal"
            controller_state_tracker.set_controller_unrequired(config.controller_name)
            return result_msg

        # 获取result
        result_future = action_client._get_result_async(controller_goal_handle)
        start_time = time.time()
        while not result_future.done() and (time.time() - start_time) < 60.0:
            pass

        if not result_future.done():
            self.get_logger().error(f"Timeout waiting for result: {action_name}")
            result_msg = config.create_result_msg(None)
            result_msg.success = False
            result_msg.result_msg = "Timeout waiting for result"
            controller_state_tracker.set_controller_unrequired(config.controller_name)
            return result_msg

        result_future_obj = result_future.result()
        if result_future_obj is None:
            self.get_logger().error(f"Failed to get result: {action_name}")
            result_msg = config.create_result_msg(None)
            result_msg.success = False
            result_msg.result_msg = "Failed to get result"
            controller_state_tracker.set_controller_unrequired(config.controller_name)
            return result_msg

        controller_result = result_future_obj.result
        result_msg = config.create_result_msg(controller_result)

        self.get_logger().info(f"Action completed with success={controller_result.success}")
        controller_state_tracker.set_controller_unrequired(config.controller_name)
        return result_msg


def main(args=None):
    """主入口"""
    rclpy.init(args=args)
    node = XArmActionManagerNode()
    node.get_logger().info('xarm_action_manager node started')
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
